const m = $json.message || $json.edited_message || {};
const chat_id = String(m.chat?.id ?? '');
const first_name = m.from?.first_name || 'Athlete';
const text = String(m.text || m.caption || '').trim();
let command = 'chat', args = text;
if (m.location) { command = 'eat'; args = ''; }
else if (text.startsWith('/')) {
  const [c, ...rest] = text.split(/\s+/);
  command = c.slice(1).split('@')[0].toLowerCase();
  args = rest.join(' ').trim();
}
const known = ['start', 'help', 'link', 'today', 'workout', 'eat', 'done', 'log', 'report', 'stop', 'chat'];
if (!known.includes(command)) command = 'help';
if (command === 'start') command = 'help';
return [{ json: { chat_id, first_name, text, command, args,
  lat: m.location?.latitude ?? null, lon: m.location?.longitude ?? null } }];

const cmd = $('Parse Command').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.chat_id);
const sub = rows.find(r => String(r.chat_id) === cmd.chat_id) || null;
const linked = !!(sub && sub.email && sub.active !== 'no');
const needsAccount = ['today', 'workout', 'done', 'log', 'report'];
const route = (!linked && needsAccount.includes(cmd.command)) ? 'notlinked' : cmd.command;
return [{ json: { ...cmd, linked, sub: sub || {}, route } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const aiText = j => String(j?.choices?.[0]?.message?.content || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
