const today = $now.toFormat('yyyy-MM-dd');
const bar = (v, t) => { const p = t > 0 ? Math.min(1, v / t) : 0; const f = Math.round(p * 10); return '█'.repeat(f) + '░'.repeat(10 - f) + ' ' + Math.round(p * 100) + '%'; };
const c = $json;
const hi = c.linked ? `Welcome back, <b>${esc(c.sub.name || c.first_name)}</b>! 💪` : `Hey <b>${esc(c.first_name)}</b>, I'm your <b>GymBuddy AI</b> coach on Telegram 🏋️`;
const text = [hi, '',
  c.linked ? null : '1️⃣ First connect your app account: <code>/link your@email.com</code>\n(the email you use on GymBuddy, with daily coaching turned on in your profile)\n',
  '<b>What I can do</b>',
  '/today: your workout, calories, protein and water for today',
  '/workout: the exercise list for today (or <code>/workout legs</code>)',
  '/eat: healthy dishes in restaurants near you (send your 📍 location or <code>/eat Rabat</code>)',
  '/done: log a finished workout and grow your 🔥 streak',
  '/log 2 eggs and a banana: I estimate the macros and log the meal',
  '/report: today\'s calories and protein with progress bars',
  '/stop: pause the daily messages', '',
  'Or just ask me anything: "what can I eat after leg day?"', '',
  `Every morning at 07:30 you get your plan, at 20:30 a reminder if you haven't trained, and on Sunday a weekly recap.`,
  `📱 App: ${'https://gymbuddy-ai-phi.vercel.app'}`].filter(l => l !== null).join('\n');
return [{ json: { chat_id: c.chat_id, text } }];

