const u = d.users.find(x => (x.email || '').toLowerCase() === email);
if (!u) return [{ json: { ok: false, chat_id: c.chat_id, text: `I can't find <b>${esc(email)}</b> among members with daily coaching turned on.\nOpen ${'https://gymbuddy-ai-phi.vercel.app'} → Profile → turn on <b>daily coaching</b>, then send /link again.` } }];
const s = c.sub || {};
const rowData = { chat_id: c.chat_id, email, user_id: u.user_id, name: u.name || c.first_name,
  calories_target: u.calories, protein_g: u.protein_g, water_l: u.water_l, language: u.language || 'en',
  streak: s.streak || 0, best_streak: s.best_streak || 0, total_workouts: s.total_workouts || 0,
  last_done: s.last_done || '', active: 'yes', linked_at: $now.toISO() };
const text = `✅ Linked to <b>${esc(rowData.name)}</b>'s GymBuddy account.\n\n🎯 Goal: ${esc(u.goal)}\n🔥 ${u.calories} kcal · 🥩 ${u.protein_g} g protein · 💧 ${u.water_l} L water\n🏋️ Today: <b>${esc(u.today_workout)}</b>\n\nTry /today or /workout.`;
return [{ json: { ok: true, chat_id: c.chat_id, row: rowData, text } }];

