const d = $input.first().json;
const s = c.sub;
const u = (d.users || []).find(x => (x.email || '').toLowerCase() === String(s.email).toLowerCase());
const member = u || { name: s.name, today_workout: 'Your planned session', calories: s.calories_target,
  protein_g: s.protein_g, water_l: s.water_l, language: s.language, goal: '', diet: '', allergies: [], injuries: [], equipment: '' };
