});
const head = p.isRest ? `😴 Today is a <b>rest day</b> in your plan. If you still want to move, here is a light core & glutes session:\n\n` : '';
const text = `${head}<b>📋 ${esc(w.title)}</b>\n\n${lines.join('\n')}\n\n⏱️ Run it with the in-gym chrono: https://gymbuddy-ai-phi.vercel.app/gym\nSend /done when you finish 🔥`;
return [{ json: { chat_id: p.chat_id, text } }];

const c = $json;
const city = c.args || '';
const ok = (c.lat !== null && c.lon !== null) || city.length > 1;
return [{ json: { ok, chat_id: c.chat_id, body: { lat: c.lat, lon: c.lon, city, user_id: c.sub.user_id || null },
  kcal_target: Number(c.sub.calories_target || 0), protein_target: Number(c.sub.protein_g || 0),
  text: '📍 Send me your <b>location</b> (📎 → Location) or a city: <code>/eat Casablanca</code>' } }];

