const q = $('Restaurant Query').first().json;
const r = $input.first().json;
const list = (r.restaurants || []).slice(0, 4);
const mealBudget = q.kcal_target ? Math.round(q.kcal_target / 3) : 0;
if (!list.length) {
  const text = `🍽️ I couldn't find restaurants near <b>${esc(r.location || q.body.city || 'you')}</b> right now.\n\nSafe picks almost everywhere:\n• Grilled chicken or fish + vegetables + rice (sauce on the side)\n• Poke / salad bowl with double protein\n• Omelette + salad + bread\n\nTry a bigger city name, e.g. <code>/eat Rabat</code>.`;
  return [{ json: { chat_id: q.chat_id, text } }];
}
const lines = list.map((x, i) => {
  const fit = mealBudget ? (x.est_kcal <= mealBudget * 1.1 ? '✅ fits your meal budget' : '⚠️ above your meal budget, skip the bread or share a side') : '';
  return `${i + 1}. <b>${esc(x.name)}</b> · ${esc(x.cuisine)} · ${x.distance_km} km\n   🍽️ ${esc(x.recommended_dish)}\n   ~${x.est_kcal} kcal · ${x.est_protein_g} g protein ${fit}\n   <a href="${esc(x.maps_url)}">Open in Maps</a>`;
});
const text = `<b>🥗 Healthy picks near ${esc(r.location)}</b>${mealBudget ? `\nYour budget per meal: ~${mealBudget} kcal, ${Math.round(q.protein_target / 3)} g protein` : ''}\n\n${lines.join('\n\n')}\n\nAfter you eat, log it with <code>/log</code> + what you ate.`;
return [{ json: { chat_id: q.chat_id, text } }];

