const bar = (v, t) => { const p = t > 0 ? Math.min(1, v / t) : 0; const f = Math.round(p * 10); return '█'.repeat(f) + '░'.repeat(10 - f) + ' ' + Math.round(p * 100) + '%'; };
const c = $json; const s = c.sub;
const last = s.last_done ? DateTime.fromISO(String(s.last_done)) : null;
const gap = last && last.isValid ? Math.floor($now.startOf('day').diff(last.startOf('day'), 'days').days) : 999;
let streak = Number(s.streak || 0);
const already = gap === 0;
if (!already) streak = gap <= 3 ? streak + 1 : 1;   // up to 2 rest days in a row keep the streak alive
const best = Math.max(Number(s.best_streak || 0), streak);
const total = Number(s.total_workouts || 0) + (already ? 0 : 1);
const badges = { 3: '🥉 3-workout streak', 7: '🥈 7-workout streak', 14: '🥇 14-workout streak', 30: '🏆 30-workout streak', 50: '💎 50-workout legend' };
const hype = ['Beast mode 🦍', 'That is how progress is built 🧱', 'Future you says thanks 🙌', 'One more brick in the wall 💪', 'Consistency beats motivation 🔁'];
let text;
if (already) text = `You already logged a workout today ✅ Streak stays at <b>${streak}</b> 🔥\nRest well and hit your protein (${s.protein_g || '?'} g).`;
else {
  text = `<b>${hype[total % hype.length]}</b>\n\n✅ Workout #${total} logged${c.args ? `: ${esc(c.args)}` : ''}\n🔥 Streak: <b>${streak}</b> (best ${best})`;
  if (badges[streak]) text += `\n\n🎖️ New badge unlocked: <b>${badges[streak]}</b>!`;
  text += `\n\nRecovery: eat ~${Math.round((s.protein_g || 120) / 3)} g protein in the next 2 hours and drink water 💧`;
}
return [{ json: { chat_id: c.chat_id, text, already, streak, best, total, workout: c.args || '' } }];

