try { const raw = aiText($input.first().json); m = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { m = null; }
const ok = m && Number(m.calories) > 0;
const r = { chat_id: q.chat_id, date: today, time: $now.toFormat('HH:mm'), meal: ok ? String(m.meal || q.meal) : q.meal,
  calories: ok ? Math.round(m.calories) : 0, protein_g: ok ? Math.round(m.protein_g || 0) : 0,
