r.text = ok
  ? `🍽️ Logged: <b>${esc(r.meal)}</b>\n🔥 ${r.calories} kcal · 🥩 ${r.protein_g} g protein · 🍚 ${r.carbs_g} g carbs · 🥑 ${r.fat_g} g fat\n${m.tip ? `\n💡 ${esc(m.tip)}\n` : ''}\nSee your day with /report`
  : `🍽️ Logged <b>${esc(q.meal)}</b>, but I couldn't estimate the macros right now (saved as 0 kcal). Try again later or describe portions, e.g. "200 g chicken + 1 cup rice".`;
return [{ json: r }];

