const c = $('Attach Subscriber & Route').first().json; const s = c.sub;
const meals = $input.all().map(i => i.json).filter(m => String(m.chat_id) === c.chat_id && String(m.date) === today);
const sum = k => meals.reduce((a, m) => a + Number(m[k] || 0), 0);
const kcal = sum('calories'), prot = sum('protein_g');
const tK = Number(s.calories_target || 0), tP = Number(s.protein_g || 0);
let text = `<b>📊 Today's nutrition</b> (${today})\n\n🔥 Calories ${kcal} / ${tK}\n${bar(kcal, tK)}\n🥩 Protein ${prot} / ${tP} g\n${bar(prot, tP)}\n💧 Water goal: ${s.water_l || '?'} L\n`;
if (!meals.length) text += `\nNo meals logged yet. Use <code>/log</code> + what you ate.`;
else {
  text += `\n<b>Meals</b>\n` + meals.map(m => `• ${esc(m.time)} ${esc(m.meal)} (${m.calories} kcal, ${m.protein_g} g)`).join('\n');
